{
  "lemmas": [
    {
      "lemma": "property lemma_1; @(posedge clk) disable iff (rst) (c >= 0 && c <= 23); endproperty",
      "explanation": "Bounds the iteration count. Together with lemma_3, c = 23 implies x = 15, so the loop cannot increment c again."
    },
    {
      "lemma": "property lemma_2; @(posedge clk) disable iff (rst) (y == (int'(c) - 6)); endproperty",
      "explanation": "Captures the lockstep increments of y and c from their reset values, making y positive when c reaches 23."
    },
    {
      "lemma": "property lemma_3; @(posedge clk) disable iff (rst) (x == (-100 + ((int'(c) * (int'(c) - 13)) / 2))); endproperty",
      "explanation": "Captures the cumulative updates to x. Over the bounded count range, x is nonnegative only at c = 23."
    },
    {
      "lemma": "property lemma_4; @(posedge clk) disable iff (rst) (state == DONE |-> c == 23); endproperty",
      "explanation": "Connects loop termination to the count: entering DONE requires nonnegative x, which lemmas 1 and 3 permit only at c = 23. Lemma 2 then establishes the target."
    }
  ]
}
